func:
// Settings of the tab Chartres live. In: a request of Power Automate (msg.req)
// or the refresh trigger. Out 1: the request. Out 2: the reference refresh.
// Edit the constants below. DRY_RUN true builds and logs the rows, writes none.
var DRY_RUN = true;
var SITE_NAME = 'Chartres';
var SOURCE = 'excel';

var shared = glob.get('cfg');
if (!shared || !shared.root) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'CONFIG not run'
  });
  node.error('CONFIG not run: open the Config tab and deploy it');
  return null;
}

var cfg = Object.assign({}, shared);
cfg.site = SITE_NAME;
cfg.source = SOURCE;
cfg.dryRun = DRY_RUN;
cfg.referenceFolder = shared.root + '/reference';
cfg.liveFolder = shared.root + '/report';
flow.set('cfg', cfg);

node.status({
  fill: DRY_RUN ? 'yellow' : 'green',
  shape: 'dot',
  text: SITE_NAME + (DRY_RUN ? ' DRY RUN' : ' WRITE MODE')
});
if (msg.req) {
  return [msg, null];
}
return [null, msg];

// Checks and reads one Base row from Power Automate. In: msg.payload (JSON).
// Out 1: msg.row {fileLine, iso, saved, base}. Out 2: the answer for a bad
// row (400) or a day before FIRST_DAY (200, not written).

// First production day written by this tab (the days before stay in the
// month files of the history load).
var FIRST_DAY = '2026-11-11';
var SAVED_COLUMN = 'Date et heure de la saisie';

function norm(value) {
  var text = value === undefined || value === null ? '' : String(value);
  return text.replace(/\s+/g, ' ').trim();
}

function reply(code, tag, detail) {
  msg.statusCode = code;
  msg.payload = {
    status: tag,
    detail: detail
  };
  msg.logLevel = code === 200 ? 'info' : 'warn';
  msg.logText = tag + ': ' + detail;
  return [null, msg];
}

var body = msg.payload;
if (!body || typeof body !== 'object' || Array.isArray(body)) {
  return reply(400, 'rejected', 'the body is not a JSON object');
}

// Same header spelling as the workbook sheet Base.
var base = {};
Object.keys(body).forEach(function (name) {
  base[norm(name).replace('Week-end', 'Weekend')] = body[name];
});

// The line is the workbook name: OEE <line> - <year>.xlsm
var fileName = norm(base.FileName);
var fileLine = fileName
  .replace(/^OEE /, '')
  .replace(/ - \d{4}\.xlsm?$/i, '');
if (!fileName || !fileLine) {
  return reply(400, 'rejected', 'FileName is missing');
}

// The day is ANNEE / MOIS / JOUR (the stored Date is off by a day on
// some rows).
var year = Number(base.ANNEE) || 0;
var month = Number(base.MOIS) || 0;
var dayOfMonth = Number(base.JOUR) || 0;
var iso = String(year) + '-' + ('0' + month).slice(-2) + '-' +
  ('0' + dayOfMonth).slice(-2);
var valid = year > 2000 && month >= 1 && month <= 12 && dayOfMonth >= 1;
if (valid) {
  var check = new Date(iso + 'T00:00:00Z');
  valid = !isNaN(check.getTime()) &&
    check.toISOString().slice(0, 10) === iso;
}
if (!valid) {
  return reply(400, 'rejected', fileLine + ': no valid ANNEE/MOIS/JOUR');
}
if (iso < FIRST_DAY) {
  return reply(200, 'ignored', fileLine + ' ' + iso + ' is before ' +
    FIRST_DAY);
}

msg.row = {
  fileLine: fileLine,
  iso: iso,
  saved: Number(base[SAVED_COLUMN]) || 0,
  base: base
};
node.status({
  fill: 'green',
  shape: 'dot',
  text: fileLine + ' ' + iso
});
return [msg, null];

// Stops a request while the reference files are not loaded (after a deploy
// the refresh needs a few seconds). In: msg.row. Out 1: the request goes on.
// Out 2: answer 503, so Power Automate sends the row again.
var ready = flow.get('chartres_ready');
if (ready && ready.at) {
  return [msg, null];
}

msg.statusCode = 503;
msg.payload = {
  status: 'not ready',
  detail: 'reference files are loading, send again'
};
msg.logLevel = 'warn';
msg.logText = 'not ready: reference files not loaded yet';
return [null, msg];

// Starts one reference refresh: one message per reference file type.
// In: the refresh trigger. Out: msg.payload = the list of types, msg.runId.
var TYPES = [
  'machines',
  'glidepaths',
  'formats',
  'scope',
  'losses'
];

var runId = Date.now();
flow.set('chartres_run', {
  id: runId,
  total: TYPES.length,
  done: {},
  failed: []
});
msg.runId = runId;
msg.payload = TYPES;
return msg;

// Sets the folder of one reference file type for the list objects node.
// In: msg.payload = one type (after the split). Out: msg.type, msg.site,
// msg.what and msg.path = the folder, ending with a slash.
var SITE = 'Chartres';
var FOLDERS = {
  machines: 'machine_names/site=Chartres/',
  glidepaths: 'glidepaths/site=Chartres/',
  formats: 'format_list/site=Chartres/',
  scope: 'report_scope/site=All/',
  losses: 'localisation/site=Chartres/'
};
var cfg = flow.get('cfg');

msg.type = msg.payload;
msg.site = SITE;
msg.what = msg.type;
msg.path = cfg.referenceFolder + '/' + FOLDERS[msg.type];
return msg;

// Picks the newest .csv of the folder list (list objects).
// Out 1: msg.path for the read node, without data/ten=<tenant>/ or a leading
// slash. Out 2: a failed item when the folder has no .csv.
var TENANT_PREFIX = /^\/?(data\/ten=[^\/]+\/)?/;
var items = Array.isArray(msg.payload) ? msg.payload : [];
var files = items.filter(function (item) {
  return /\.csv$/i.test(item.key);
});

if (!files.length) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'no csv file for ' + msg.site
  });
  msg.payload = {
    name: msg.site,
    failed: msg.what + ' ' + msg.site + ': no csv file in ' + msg.path,
    skipped: null,
    rows: []
  };
  return [null, msg];
}

files.sort(function (a, b) {
  return String(b.lastModified).localeCompare(String(a.lastModified));
});
msg.path = String(files[0].key).replace(TENANT_PREFIX, '');
node.status({
  fill: 'green',
  shape: 'dot',
  text: msg.path.slice(-40)
});
return [msg, null];

// Sends the parsed file to the lookup node of its type.
// In: msg.type, msg.payload = the parsed rows. Out 1: machines, 2: glidepaths,
// 3: format list, 4: report scope, 5: loss names.
var ORDER = [
  'machines',
  'glidepaths',
  'formats',
  'scope',
  'losses'
];

var out = [
  null,
  null,
  null,
  null,
  null
];
var index = ORDER.indexOf(msg.type);
if (index !== -1) {
  out[index] = msg;
}
return out;

// Machine lookup of one site from its Machine Names file. In: msg.payload =
// parsed rows; stores flow context machines_<Site>: MachineName -> Dept,
// Area, Product Type, for every machine of the file (the EU scope is the
// column In EU Report, from the report scope file). Out 2: a failed item.
var site = msg.site;
var rows = Array.isArray(msg.payload) ? msg.payload : [];
if (!rows.length || rows[0].MachineName === undefined) {
  msg.payload = {
    failed: 'machine names ' + site + ': no MachineName column or rows'
  };
  return [null, msg];
}

function text(value) {
  return value === undefined || value === null ? '' : String(value).trim();
}

var lookup = {};
var kept = 0;
rows.forEach(function (row) {
  var name = text(row.MachineName);
  if (!name) {
    return;
  }
  lookup[name] = {
    'Dept': text(row.Dept),
    'Area': text(row.Area),
    'Product Type': text(row['Product Type'])
  };
  kept++;
});
flow.set('machines_' + site, lookup);
node.status({
  fill: 'green',
  shape: 'dot',
  text: site + ': ' + kept + ' machines'
});
msg.payload = site;
return [msg, null];

// Builds the target lookup of one site from its Glidepaths file.
// In: msg.payload = parsed rows (Site Name, Line, OEE Bucket, month columns).
// Stores flow context targets_<site>: machine-site -> month 01/MM/YYYY ->
// {oee, pdt, updt, b: {bucket: value}}. Out 2: a failed item for an empty file.
var BUCKETS = {
  '% OEE': 'oee',
  'Planned Downtime (Total)': 'pdt',
  'Unplanned Downtime (Total)': 'updt'
};
// The file starts with a byte order mark: it sits in the first column name.
function clean(row) {
  var out = {};
  Object.keys(row).forEach(function (column) {
    out[column.replace(/\uFEFF/g, '')] = row[column];
  });
  return out;
}

var rows = Array.isArray(msg.payload) ? msg.payload.map(clean) : [];
if (!rows.length || rows[0].Line === undefined) {
  msg.payload = {
    failed: 'glidepaths ' + msg.site + ': no Line column or rows'
  };
  return [null, msg];
}

var lookup = {};
var cells = 0;
rows.forEach(function (row) {
  if (!row.Line || !row['Site Name'] || !row['OEE Bucket']) {
    return;
  }
  var field = BUCKETS[row['OEE Bucket']];
  var key = row.Line + '-' + row['Site Name'];
  Object.keys(row).forEach(function (column) {
    var value = String(row[column]).trim();
    if (!/^\d{2}\/\d{2}\/\d{4}$/.test(column) || value === '') {
      return;
    }
    var number = Number(value);
    if (isNaN(number)) {
      return;
    }
    lookup[key] = lookup[key] || {};
    lookup[key][column] = lookup[key][column] || {};
    lookup[key][column].b = lookup[key][column].b || {};
    lookup[key][column].b[row['OEE Bucket']] = number;
    if (field) {
      lookup[key][column][field] = number;
    }
    cells++;
  });
});
flow.set('targets_' + msg.site, lookup);
node.status({
  fill: 'green',
  shape: 'dot',
  text: msg.site + ': ' + cells + ' target values'
});
msg.payload = msg.site;
return [msg, null];

// Format lookup of one site from its Format List file. In: msg.payload =
// parsed rows; stores flow context formats_<Site>: Product Key (MachineName-
// Site + space + Product Name) -> Brand, Unit Size, Unit Count/Format,
// Extra Info. Out: msg.payload = the site, for the next setup lane.
var COLUMNS = [
  'Brand',
  'Unit Size',
  'Unit Count/Format',
  'Extra Info'
];
var site = msg.site;
var rows = Array.isArray(msg.payload) ? msg.payload : [];

// As in the report: trailing spaces go, an empty cell is empty (null).
function cell(value) {
  if (value === undefined || value === null) {
    return null;
  }
  var text = String(value).replace(/\s+$/, '');
  return text === '' ? null : text;
}

var lookup = {};
var kept = 0;
rows.forEach(function (row) {
  var machine = cell(row.MachineName);
  var product = cell(row['Product Name']);
  if (!machine || !product) {
    return;
  }
  var item = {};
  COLUMNS.forEach(function (column) {
    item[column] = cell(row[column]);
  });
  lookup[machine + '-' + site + ' ' + product] = item;
  kept++;
});
flow.set('formats_' + site, lookup);
node.status({
  fill: 'green',
  shape: 'dot',
  text: site + ': ' + kept + ' formats'
});
msg.payload = site;
return msg;

// Builds the EU report scope of one site from the report scope file.
// In: msg.payload = parsed rows (Site, Tables, Rule, Column, Value). Stores
// flow context scope_<Site>: table -> {keep: {column: [values]}, drop: ...}.
// Out 2: a failed item when the file has no rows or columns.
var RULES = [
  'keep',
  'drop'
];

var rows = Array.isArray(msg.payload) ? msg.payload : [];
var site = msg.site;

function text(value) {
  return value === undefined || value === null ? '' : String(value).trim();
}

// A byte order mark can sit in the first column name.
function siteOf(row) {
  return text(row.Site !== undefined ? row.Site : row['\uFEFFSite']);
}

var ok = rows.some(function (row) {
  return row.Tables !== undefined && row.Rule !== undefined;
});
if (!ok) {
  msg.payload = {
    failed: 'report scope: no Tables / Rule columns or rows'
  };
  return [null, msg];
}

var scope = {};
var ruleCount = 0;
rows.forEach(function (row) {
  var rule = text(row.Rule).toLowerCase();
  var column = text(row.Column);
  var value = text(row.Value);
  if (siteOf(row) !== site || RULES.indexOf(rule) === -1 || !column) {
    return;
  }
  text(row.Tables).split(';').forEach(function (name) {
    var table = text(name);
    if (!table) {
      return;
    }
    scope[table] = scope[table] || {
      keep: {},
      drop: {}
    };
    var list = scope[table][rule];
    list[column] = list[column] || [];
    list[column].push(value);
    ruleCount++;
  });
});
flow.set('scope_' + site, scope);
node.status({
  fill: 'green',
  shape: 'dot',
  text: site + ': ' + ruleCount + ' scope rules'
});
msg.payload = site;
return [msg, null];

// Builds the loss names lookup from the file chartres-losses.csv.
// In: msg.payload = parsed rows (Line, Column, Group, Sub Group, Description,
// Equipment). Stores flow context losses_Chartres: Line|Column -> [group,
// sub group, description, equipment]. Out 2: a failed item.
var rows = Array.isArray(msg.payload) ? msg.payload : [];

// A byte order mark can sit in the first column name.
function clean(row) {
  var out = {};
  Object.keys(row).forEach(function (column) {
    out[column.replace(/﻿/g, '')] = row[column];
  });
  return out;
}

var lookup = {};
var kept = 0;
rows.map(clean).forEach(function (row) {
  if (!row.Line || !row.Column) {
    return;
  }
  lookup[row.Line + '|' + row.Column] = [
    row.Group,
    row['Sub Group'],
    row.Description,
    row.Equipment
  ];
  kept++;
});
if (!kept) {
  msg.payload = {
    failed: 'loss names: no Line / Column rows'
  };
  return [null, msg];
}
flow.set('losses_Chartres', lookup);
node.status({
  fill: 'green',
  shape: 'dot',
  text: kept + ' loss names'
});
msg.payload = 'Chartres';
return [msg, null];

// Counts the lookups of one refresh. In: msg.type, msg.runId and msg.payload
// (the site name, or {failed}). When all types are in and none failed, the
// reference is ready for the requests. Out: a log line when the run ends.
var run = flow.get('chartres_run');
if (!run || run.id !== msg.runId) {
  return null;
}

var failed = msg.payload && msg.payload.failed;
if (failed) {
  run.failed.push(String(failed));
}
run.done[msg.type] = true;
flow.set('chartres_run', run);
if (Object.keys(run.done).length < run.total) {
  return null;
}

var text = 'reference loaded';
var level = 'info';
if (run.failed.length) {
  text = 'reference FAILED: ' + run.failed.join('; ');
  level = 'failed';
} else {
  flow.set('chartres_ready', {
    at: Date.now()
  });
}
node.status({
  fill: level === 'info' ? 'green' : 'red',
  shape: 'dot',
  text: text.slice(0, 40)
});
var day = new Date().toISOString().slice(0, 10);
return {
  payload: day + ' [reference] ' + text,
  level: level,
  source: 'chartres-live'
};

// Builds the Plan_OPT_EU rows (one per product slot) and the
// Time_Utilisation_EU row of the day. In: msg.row (y1) and the lookups in
// flow context (machines, scope, targets, formats of Chartres). Out 1:
// msg.rows, slots, line, targets. Out 2: 400 for an unknown line.
var SITE = 'Chartres';
var DATA_SOURCE = 'Excel';
var ALL_TIME = 1440;
// Shift types of the workbook: report shift name and start hour (site
// answer 2026-11). Time_Utilisation uses TOR as the planned time.
var SHIFTS = [
  ['Semaine Matin', 'Morning', 5],
  ['Semaine Après Midi', 'Afternoon', 13],
  ['Semaine Nuit', 'Night', 21],
  ['Weekend Matin', 'Morning', 5],
  ['Weekend Nuit', 'Night', 17]
];
var HOUR_MS = 3600000;
var FORMAT_COLUMNS = [
  'Brand',
  'Unit Size',
  'Unit Count/Format',
  'Extra Info'
];

function norm(value) {
  var text = value === undefined || value === null ? '' : String(value);
  return text.replace(/\s+/g, ' ').trim();
}

function key(value) {
  return norm(value)
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/[\s-]/g, '')
    .toUpperCase();
}

function num(value) {
  if (value === '' || value === undefined || value === null) {
    return 0;
  }
  return Number(value) || 0;
}

var row = msg.row;
var machines = flow.get('machines_' + SITE) || {};
var scope = flow.get('scope_' + SITE) || {};
var machine = null;
Object.keys(machines).forEach(function (name) {
  if (key(name) === key(row.fileLine)) {
    machine = name;
  }
});
if (machine === null) {
  msg.statusCode = 400;
  msg.payload = {
    status: 'rejected',
    detail: 'line not in Machine Names: ' + row.fileLine
  };
  msg.logLevel = 'warn';
  msg.logText = 'rejected: line not in Machine Names: ' + row.fileLine;
  return [null, msg];
}

// The EU report scope rules (keep / drop) of one table, as in the filler.
function inEuReport(table) {
  var rules = scope[table] || {
    keep: {},
    drop: {}
  };
  var candidate = {
    MachineName: machine
  };
  var kept = Object.keys(rules.keep).every(function (column) {
    return rules.keep[column].indexOf(norm(candidate[column])) !== -1;
  });
  var dropped = Object.keys(rules.drop).some(function (column) {
    return rules.drop[column].indexOf(norm(candidate[column])) !== -1;
  });
  return kept && !dropped;
}

var info = machines[machine];
var line = {
  machine: machine,
  unique: machine + '-' + SITE,
  areaName: info.Area,
  dept: info.Dept,
  area: info.Area,
  type: info['Product Type'],
  inEu: {
    Plan_OPT_EU: inEuReport('Plan_OPT_EU'),
    Time_Utilisation_EU: inEuReport('Time_Utilisation_EU'),
    Daily_Losses_EU: inEuReport('Daily_Losses_EU'),
    Volume_CoV_EU: inEuReport('Volume_CoV_EU')
  }
};

var base = row.base;
var iso = row.iso;
var month = iso.slice(0, 7);
var unique = line.unique;
var dayNumber = Date.parse(iso + 'T00:00:00Z') / 86400000;
var loadedAt = Date.now();
// Glidepaths are in percent: OEE as in the history (one decimal), the
// downtime and loss targets as fractions.
var allTargets = flow.get('targets_' + SITE) || {};
var targets = (allTargets[unique] || {})[
  '01/' + iso.slice(5, 7) + '/' + iso.slice(0, 4)
] || {};

function fraction(percent) {
  if (percent === undefined) {
    return null;
  }
  return Number((percent / 100).toPrecision(12));
}

var oeeTarget = targets.oee === undefined ? null :
  Math.round(targets.oee * 10) / 10;
var pdt = fraction(targets.pdt);
var updt = fraction(targets.updt);
var machineColumns = {
  Dept: line.dept,
  Area: line.area,
  'Product Type': line.type
};

// Product slots: 5 shift types x PF1 to PF4.
var slots = [];
SHIFTS.forEach(function (shift) {
  for (var k = 1; k <= 4; k++) {
    var suffix = ' PF' + k + ' ' + shift[0];
    var slot = {
      type: shift[0],
      shift: shift[1],
      start: shift[2],
      code: norm(base['Code' + suffix]),
      name: norm(base['Nom' + suffix]),
      time: num(base['Temps' + suffix]),
      volume: num(base['Volume' + suffix]),
      waste: num(base['Déchets' + suffix]),
      speed: num(base['Vitesse' + suffix])
    };
    if (slot.code || slot.time || slot.volume) {
      slots.push(slot);
    }
  }
});

var formats = flow.get('formats_' + SITE) || {};
var plan = [];
var capacityDay = 0;
slots.forEach(function (slot) {
  // Good Parts = Volume - Déchets (user, 2026-11-10).
  var good = slot.volume - slot.waste;
  var capacity = slot.speed * slot.time;
  var part = slot.name || slot.code;
  capacityDay += capacity;
  var planRow = {
    Date: dayNumber,
    AreaName: line.areaName,
    MachineName: machine,
    ShiftName: slot.shift,
    PartName: part,
    'Good Parts': good,
    Capacity: capacity,
    'Total Time': Math.trunc(slot.time),
    'Planned OpT': Math.trunc(slot.time),
    'OEE Time': slot.speed ? Math.trunc(good / slot.speed) : null,
    'Downtime Units': capacity - good,
    SiteName: SITE,
    'Unique Machine Name': unique,
    'Product Key': unique + ' ' + part,
    'UPDT Target': updt,
    'PDT Target': pdt,
    'OEE Target': oeeTarget,
    'Defect Parts': slot.waste,
    OEE: capacity ? Math.round((good / capacity) * 1000) / 1000 : null,
    'Shift Colour': null,
    ShiftStartTime: slot.start * HOUR_MS,
    Target: capacity,
    'Targets Key': machine + ' 01/' + iso.slice(5, 7) + '/' +
      iso.slice(0, 4),
    'Data Source': DATA_SOURCE,
    'In EU Report': line.inEu.Plan_OPT_EU,
    source_hours: null,
    loaded_at: loadedAt
  };
  Object.keys(machineColumns).forEach(function (name) {
    planRow[name] = machineColumns[name];
  });
  // The Format List columns, joined on Product Key.
  var format = formats[planRow['Product Key']] || {};
  FORMAT_COLUMNS.forEach(function (name) {
    planRow[name] = format[name] === undefined ? null : format[name];
  });
  plan.push(planRow);
});

var tor = num(base.TOR);
var time = {
  Date: dayNumber,
  MachineName: machine,
  'OEE Time Total': num(base.TU),
  'Total Time Total': tor,
  'Planned OPT Total': tor,
  SiteName: SITE,
  'Unique Machine Name': unique,
  'All Time': ALL_TIME,
  'Data Source': DATA_SOURCE,
  'In EU Report': line.inEu.Time_Utilisation_EU,
  loaded_at: loadedAt
};
Object.keys(machineColumns).forEach(function (name) {
  time[name] = machineColumns[name];
});

msg.line = line;
msg.targets = targets;
msg.slots = slots;
msg.day = {
  iso: iso,
  dayNumber: dayNumber,
  machine: machine,
  capacity: capacityDay,
  loadedAt: loadedAt
};
msg.rows = {
  Plan_OPT_EU: plan,
  Time_Utilisation_EU: [time]
};
return [msg, null];

// Builds the Daily_Losses_EU rows: one per loss column (NR to the first
// product column, no "Nbre") with minutes above 0. In: msg.row, slots, day,
// line, targets, rows (y2) and the loss names in flow context.
// Out: msg.rows.Daily_Losses_EU, lossShift, notes.
var SITE = 'Chartres';
var DATA_SOURCE = 'Excel';
var HOUR_MS = 3600000;
// The losses of a day go to the plan shift with the most Temps (ties: the
// first of this list). No plan slot that day: Morning at 05:00.
var SHIFT_ORDER = ['Morning', 'Afternoon', 'Night'];
var NO_PLAN_SHIFT = {
  name: 'Morning',
  start: 5 * HOUR_MS
};
var FORMAT_COLUMNS = [
  'Brand',
  'Unit Size',
  'Unit Count/Format',
  'Extra Info'
];
var MACHINE_LOSS = /^(Dysf|Pannes?|Réglages?) /;
// Block rule for a loss column that is not in the loss names file: the start
// of the column name gives group and sub group (same as the history load).
var PREFIX = [
  ['^Dysf ', 'Unplanned Loss', 'Minor Stops'],
  ['^Pannes? ', 'Unplanned Loss', 'Breakdown'],
  ['^Réglages? ', 'Unplanned Loss', 'Adjustments'],
  ['^Orga', 'Planned Loss', 'Cleaning'],
  ['^Changement', 'Planned Loss', 'Product Changeover'],
  ['^Rupture', 'Unplanned Loss', 'Lack Of Resources'],
  ['^Qualité', 'Unplanned Loss', 'Quality Issues'],
  ['^Maintenance', 'Planned Loss', 'Planned Maintenance']
];
var FIRST_PRODUCT_COLUMN = 'Code PF1 Semaine Matin';

function norm(value) {
  var text = value === undefined || value === null ? '' : String(value);
  return text.replace(/\s+/g, ' ').trim();
}

function num(value) {
  if (value === '' || value === undefined || value === null) {
    return 0;
  }
  return Number(value) || 0;
}

var base = msg.row.base;
var iso = msg.day.iso;
var machine = msg.day.machine;
var line = msg.line;
var unique = line.unique;
var losses = flow.get('losses_' + SITE) || {};
var notes = [];
var targets = msg.targets.b || {};

// Shift of the losses.
function shiftOfLosses(slots) {
  if (!slots.length) {
    return NO_PLAN_SHIFT;
  }
  var byShift = {};
  var byType = {};
  slots.forEach(function (slot) {
    byShift[slot.shift] = (byShift[slot.shift] || 0) + slot.time;
    byType[slot.type] = (byType[slot.type] || 0) + slot.time;
  });
  var name = SHIFT_ORDER
    .filter(function (shift) {
      return byShift[shift] !== undefined;
    })
    .reduce(function (a, b) {
      return byShift[b] > byShift[a] ? b : a;
    });
  var type = Object.keys(byType)
    .filter(function (t) {
      return slots.some(function (s) {
        return s.type === t && s.shift === name;
      });
    })
    .reduce(function (a, b) {
      return byType[b] > byType[a] ? b : a;
    });
  var start = slots.filter(function (s) {
    return s.type === type;
  })[0].start;
  return {
    name: name,
    start: start * HOUR_MS
  };
}

// Names of one loss column: the map of the history load, else the block
// rule of the column name.
function names(column) {
  var known = losses[machine + '|' + column];
  if (known) {
    return {
      group: known[0],
      sub: known[1],
      desc: known[2],
      equipment: known[3]
    };
  }
  notes.push('loss column not in the map: ' + column);
  var rule = null;
  PREFIX.forEach(function (p) {
    if (!rule && new RegExp(p[0]).test(column)) {
      rule = p;
    }
  });
  var group = rule ? rule[1] : 'Unplanned Loss';
  var sub = rule ? rule[2] : 'Not Logged';
  var machineLoss = rule !== null && group === 'Unplanned Loss' &&
    MACHINE_LOSS.test(column);
  var desc = machineLoss ? column.replace(new RegExp(rule[0]), '') : column;
  return {
    group: group,
    sub: sub,
    desc: desc,
    equipment: machineLoss ? desc : 'Unclassed'
  };
}

var keys = Object.keys(base);
var first = keys.indexOf('NR');
var last = keys.indexOf(FIRST_PRODUCT_COLUMN);
if (first === -1 || last === -1 || last < first) {
  msg.statusCode = 400;
  msg.payload = {
    status: 'rejected',
    detail: 'NR or ' + FIRST_PRODUCT_COLUMN + ' is missing'
  };
  msg.logLevel = 'warn';
  msg.logText = 'rejected: NR or ' + FIRST_PRODUCT_COLUMN + ' is missing';
  return [null, msg];
}
var columns = ['NR'];
keys.slice(first + 1, last).forEach(function (name) {
  if (!/^Nbre/i.test(name)) {
    columns.push(name);
  }
});

var slots = msg.slots;
var main = null;
slots.forEach(function (slot) {
  if (main === null || slot.time > main.time) {
    main = slot;
  }
});
var lossShift = shiftOfLosses(slots);
var dmy = iso.slice(8, 10) + '/' + iso.slice(5, 7) + '/' + iso.slice(0, 4);
var targetKeyDate = '01/' + iso.slice(5, 7) + '/' + iso.slice(0, 4);
var rows = [];
var lossMinutes = 0;
columns.forEach(function (column) {
  var minutes = num(base[column]);
  lossMinutes += minutes;
  if (minutes < 0) {
    notes.push('negative loss not loaded: ' + column + ' ' + minutes);
  }
  if (minutes <= 0) {
    return;
  }
  var n = names(column);
  var percent = targets[n.sub];
  var out = {
    Date: msg.day.dayNumber,
    Time: lossShift.start,
    MachineName: machine,
    PartName: null,
    'Shift Time': lossShift.name,
    ShiftName: lossShift.name,
    OEELossLvl3Group: n.group,
    OEELossLvl3SubGroup: n.sub,
    OEELossLvl3Desc: n.desc,
    Duration: Math.round(minutes),
    'Shift colour': null,
    SiteName: SITE,
    'Unique Machine Name': unique,
    'Breakdown Types': n.sub,
    ShiftStartDate: msg.day.dayNumber,
    Comment: null,
    'Product Key': null,
    'Volume Key': dmy + ' ' + machine + ' ' + n.group + ' ' + n.sub + ' ' +
      n.desc,
    'Loss Units': main && main.speed ? main.speed * minutes : null,
    'Time in Mins': minutes,
    'Equipment Loss Key': machine + ' ' + n.desc,
    Equipment: n.equipment,
    'Lvl 3 Loss Name': n.desc,
    'Loss Target Key': unique + ' ' + n.sub + ' ' + targetKeyDate,
    Value: null,
    'Volume Total': msg.day.capacity,
    'Loss Final Level': n.desc,
    Dept: line.dept,
    Area: line.area,
    'Product Type': line.type,
    'Data Source': DATA_SOURCE,
    'In EU Report': line.inEu.Daily_Losses_EU,
    target: percent === undefined ? null :
      Number((percent / 100).toPrecision(12)),
    'Batch ID': null,
    comment_count: null,
    loaded_at: msg.day.loadedAt
  };
  FORMAT_COLUMNS.forEach(function (name) {
    out[name] = null;
  });
  rows.push(out);
});

// The rules of the entry form: the rows are loaded, a failure is noted.
var top = num(base.TOP);
var tor = num(base.TOR);
var tu = num(base.TU);
var closed = num(base['Total Temps Fermeture']);
var slotTime = slots.reduce(function (sum, slot) {
  return sum + slot.time;
}, 0);
if (tor !== top - closed) {
  notes.push('TOR = TOP - not counted fails: ' + tor + ' vs ' + top +
    ' - ' + closed);
}
if (tu + lossMinutes !== tor) {
  notes.push('TU + NR + losses = TOR fails: ' + tu + ' + ' + lossMinutes +
    ' vs ' + tor);
}
if (slotTime !== tor) {
  notes.push('sum of product Temps = TOR fails: ' + slotTime + ' vs ' +
    tor);
}

msg.rows.Daily_Losses_EU = rows;
msg.lossShift = lossShift;
msg.notes = notes;
return [msg, null];

// Builds Volume_CoV_EU and the filler rows that keep the Tableau blend whole
// (the rule of f1-filler-rows.js, for one line and day). In: msg.rows,
// lossShift, day, line (y2, y3). Out: msg.rows.Volume_CoV_EU, filler rows
// (Data Source = Filler) in the plan and loss rows, msg.tables.
var SITE = 'Chartres';
var FILLER = 'Filler';
// Same threshold as scripts/vfc/b9-cov-rows.js.
var MIN_GOOD_PARTS = 1000;
var MINUTE_MS = 60000;
var PLAN_ZERO = [
  'Good Parts',
  'Capacity',
  'Total Time',
  'Planned OpT',
  'OEE Time',
  'Downtime Units',
  'Defect Parts',
  'source_hours'
];
var LOSS_ZERO = [
  'Duration',
  'Loss Units',
  'Volume Total',
  'Time in Mins',
  'comment_count'
];

var day = msg.day;
var machine = day.machine;
var line = msg.line;
var plan = msg.rows.Plan_OPT_EU;
var loss = msg.rows.Daily_Losses_EU;

// Volume_CoV_EU: per shift, Good Parts over MIN_GOOD_PARTS.
var groups = {};
var order = [];
plan.forEach(function (row) {
  var shift = row.ShiftName;
  if (!groups[shift]) {
    groups[shift] = {
      row: row,
      good: 0,
      time: 0,
      cap: null
    };
    order.push(shift);
  }
  var group = groups[shift];
  group.good += row['Good Parts'] || 0;
  group.time += row['Total Time'] || 0;
  if (group.cap === null || (row.Capacity || 0) > group.cap) {
    group.cap = row.Capacity;
  }
});
var cov = [];
order.forEach(function (shift) {
  var group = groups[shift];
  if (group.good <= MIN_GOOD_PARTS) {
    return;
  }
  cov.push({
    Date: day.dayNumber,
    MachineName: machine,
    'Shift Colour': shift,
    'Good Parts Sum': group.good,
    'Shift Machine Key': shift + ' ' + machine,
    'Cap Max': group.cap,
    'Time on Shift': group.time * MINUTE_MS,
    Dept: null,
    Area: null,
    'Product Type': null,
    'Unique Machine Name': line.unique,
    SiteName: SITE,
    'Data Source': 'Excel',
    'In EU Report': line.inEu.Volume_CoV_EU,
    loaded_at: day.loadedAt
  });
});
msg.rows.Volume_CoV_EU = cov;

// Filler: the machine columns shared by both tables.
function fillerBase(shift) {
  return {
    SiteName: SITE,
    'Unique Machine Name': line.unique,
    Dept: line.dept,
    Area: line.area,
    'Product Type': line.type,
    MachineName: machine,
    ShiftName: shift,
    'Data Source': FILLER,
    loaded_at: day.loadedAt,
